#include <bits/stdc++.h>

using namespace std;

#define ws " "
#define newl "\n"
#define ll long long
#define pb push_back
#define all(x) x.begin(), x.end()
#define _sz(x) (int) x.size()
#define YES cout << "YES\n"
#define NO cout << "NO\n"
#define Yes cout << "Yes\n"
#define No cout << "No\n"
#define yes cout << "yes\n"
#define no cout << "no\n"
#define scan_numbers(a, n) for (int i = 0; i < n; i++) cin >> a[i];

const int INF = (int) 1e9;
const ll ll_INF = (ll) 1e18;
const ll MOD = 1e9 + 7;

void solve() {
    int n; cin >> n;
    if (n == 1) cout << 1;
    else if (n < 4) cout << "NO SOLUTION";
    else {
        for (int i = 2; i <= n; i += 2) cout << i << ws;
        for (int i = 1; i <= n; i += 2) cout << i << ws;
    }
}

int main() {
    ios::sync_with_stdio(false); cin.tie(__null); cout.tie(__null);
    
    int t = 1;
    // cin >> t;
    
    while(t--) solve();
    
    return 0;
}